SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS `parcel_track` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `parcel_track`;
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS audit_log, sms_log, rider_cash, cod_settlements, manifest_items, manifests, shipment_events, shipments, rate_cards, users, customers, branches;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE branches (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code CHAR(3) NOT NULL UNIQUE,
  name VARCHAR(80) NOT NULL,
  city VARCHAR(60) NOT NULL UNIQUE,
  region VARCHAR(40) NOT NULL,
  address VARCHAR(200) NULL,
  phone VARCHAR(20) NULL,
  is_hub TINYINT(1) NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB;

CREATE TABLE customers (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(12) NOT NULL UNIQUE,
  full_name VARCHAR(120) NOT NULL,
  company VARCHAR(120) NULL,
  phone VARCHAR(20) NOT NULL UNIQUE,
  email VARCHAR(120) NULL,
  address VARCHAR(255) NULL,
  branch_id INT UNSIGNED NULL,
  is_credit TINYINT(1) NOT NULL DEFAULT 0,
  notes VARCHAR(255) NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (branch_id) REFERENCES branches(id)
) ENGINE=InnoDB;

CREATE TABLE users (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  username VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  full_name VARCHAR(120) NOT NULL,
  email VARCHAR(120) NULL UNIQUE,
  phone VARCHAR(20) NULL,
  role ENUM('admin','dispatcher','hub','rider','customer') NOT NULL,
  branch_id INT UNSIGNED NULL,
  customer_id INT UNSIGNED NULL,
  vehicle VARCHAR(40) NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  last_login DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (branch_id) REFERENCES branches(id),
  FOREIGN KEY (customer_id) REFERENCES customers(id)
) ENGINE=InnoDB;

CREATE TABLE rate_cards (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  service ENUM('Standard','Express','Same-day') NOT NULL,
  zone ENUM('Local','Regional','National') NOT NULL,
  base_price DECIMAL(10,2) NOT NULL,
  base_weight DECIMAL(5,2) NOT NULL DEFAULT 1.00,
  per_extra_kg DECIMAL(10,2) NOT NULL,
  transit_days TINYINT UNSIGNED NOT NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  UNIQUE KEY uq_rate (service, zone)
) ENGINE=InnoDB;

CREATE TABLE shipments (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  tracking_no VARCHAR(20) NOT NULL UNIQUE,
  customer_id INT UNSIGNED NULL,
  source ENUM('Counter','Online') NOT NULL DEFAULT 'Counter',
  sender_name VARCHAR(120) NOT NULL,
  sender_phone VARCHAR(20) NOT NULL,
  sender_address VARCHAR(255) NOT NULL,
  receiver_name VARCHAR(120) NOT NULL,
  receiver_phone VARCHAR(20) NOT NULL,
  receiver_address VARCHAR(255) NOT NULL,
  origin_branch_id INT UNSIGNED NOT NULL,
  dest_branch_id INT UNSIGNED NOT NULL,
  service ENUM('Standard','Express','Same-day') NOT NULL,
  zone ENUM('Local','Regional','National') NOT NULL,
  description VARCHAR(160) NOT NULL,
  pieces TINYINT UNSIGNED NOT NULL DEFAULT 1,
  weight_kg DECIMAL(6,2) NOT NULL,
  length_cm DECIMAL(6,1) NULL, width_cm DECIMAL(6,1) NULL, height_cm DECIMAL(6,1) NULL,
  chargeable_kg DECIMAL(6,2) NOT NULL,
  declared_value DECIMAL(12,2) NOT NULL DEFAULT 0,
  insured TINYINT(1) NOT NULL DEFAULT 0,
  fragile TINYINT(1) NOT NULL DEFAULT 0,
  cod_amount DECIMAL(12,2) NOT NULL DEFAULT 0,
  freight DECIMAL(10,2) NOT NULL,
  fuel DECIMAL(10,2) NOT NULL,
  fragile_fee DECIMAL(10,2) NOT NULL DEFAULT 0,
  cod_fee DECIMAL(10,2) NOT NULL DEFAULT 0,
  insurance_fee DECIMAL(10,2) NOT NULL DEFAULT 0,
  tax DECIMAL(10,2) NOT NULL,
  total_charge DECIMAL(10,2) NOT NULL,
  payer ENUM('Sender','Receiver') NOT NULL DEFAULT 'Sender',
  payment_status ENUM('Unpaid','Paid','Refunded') NOT NULL DEFAULT 'Unpaid',
  payment_method ENUM('Cash','Card','Online','Bank') NULL,
  paid_at DATETIME NULL,
  status ENUM('Booked','Pickup Assigned','Picked Up','At Origin Hub','In Transit','At Destination Hub','Out for Delivery','Delivered','Delivery Failed','Returning','Returned','Cancelled') NOT NULL DEFAULT 'Booked',
  pickup_date DATE NULL,
  promised_date DATE NOT NULL,
  pickup_rider_id INT UNSIGNED NULL,
  delivery_rider_id INT UNSIGNED NULL,
  delivery_otp CHAR(4) NULL,
  otp_fails TINYINT UNSIGNED NOT NULL DEFAULT 0,
  attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,
  fail_reason VARCHAR(60) NULL,
  received_by VARCHAR(120) NULL,
  delivered_at DATETIME NULL,
  notes VARCHAR(255) NULL,
  booked_by INT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CHECK (weight_kg > 0 AND weight_kg <= 50),
  CHECK (cod_amount >= 0),
  CHECK (attempts <= 3),
  INDEX idx_status (status), INDEX idx_created (created_at), INDEX idx_origin (origin_branch_id), INDEX idx_dest (dest_branch_id),
  INDEX idx_prider (pickup_rider_id), INDEX idx_drider (delivery_rider_id), INDEX idx_cust (customer_id),
  FOREIGN KEY (customer_id) REFERENCES customers(id),
  FOREIGN KEY (origin_branch_id) REFERENCES branches(id),
  FOREIGN KEY (dest_branch_id) REFERENCES branches(id),
  FOREIGN KEY (pickup_rider_id) REFERENCES users(id),
  FOREIGN KEY (delivery_rider_id) REFERENCES users(id),
  FOREIGN KEY (booked_by) REFERENCES users(id)
) ENGINE=InnoDB;

CREATE TABLE shipment_events (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  shipment_id INT UNSIGNED NOT NULL,
  status VARCHAR(30) NOT NULL,
  location VARCHAR(80) NULL,
  note VARCHAR(255) NULL,
  user_id INT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_ship (shipment_id, created_at),
  FOREIGN KEY (shipment_id) REFERENCES shipments(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id)
) ENGINE=InnoDB;

CREATE TABLE manifests (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  manifest_no VARCHAR(16) NOT NULL UNIQUE,
  from_branch_id INT UNSIGNED NOT NULL,
  to_branch_id INT UNSIGNED NOT NULL,
  vehicle_no VARCHAR(20) NULL,
  driver_name VARCHAR(80) NULL,
  status ENUM('Open','Dispatched','Received') NOT NULL DEFAULT 'Open',
  created_by INT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  dispatched_at DATETIME NULL,
  received_at DATETIME NULL,
  received_by INT UNSIGNED NULL,
  FOREIGN KEY (from_branch_id) REFERENCES branches(id),
  FOREIGN KEY (to_branch_id) REFERENCES branches(id),
  FOREIGN KEY (created_by) REFERENCES users(id),
  FOREIGN KEY (received_by) REFERENCES users(id)
) ENGINE=InnoDB;

CREATE TABLE manifest_items (
  manifest_id INT UNSIGNED NOT NULL,
  shipment_id INT UNSIGNED NOT NULL,
  received TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (manifest_id, shipment_id),
  FOREIGN KEY (manifest_id) REFERENCES manifests(id) ON DELETE CASCADE,
  FOREIGN KEY (shipment_id) REFERENCES shipments(id)
) ENGINE=InnoDB;

CREATE TABLE cod_settlements (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  settle_no VARCHAR(16) NOT NULL UNIQUE,
  rider_id INT UNSIGNED NOT NULL,
  amount DECIMAL(12,2) NOT NULL,
  items INT UNSIGNED NOT NULL,
  note VARCHAR(160) NULL,
  settled_by INT UNSIGNED NULL,
  settled_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (rider_id) REFERENCES users(id),
  FOREIGN KEY (settled_by) REFERENCES users(id)
) ENGINE=InnoDB;

CREATE TABLE rider_cash (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  rider_id INT UNSIGNED NOT NULL,
  shipment_id INT UNSIGNED NOT NULL,
  kind ENUM('COD','Delivery freight','Pickup freight') NOT NULL,
  amount DECIMAL(12,2) NOT NULL,
  settlement_id INT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (amount > 0),
  INDEX idx_rider (rider_id, settlement_id),
  FOREIGN KEY (rider_id) REFERENCES users(id),
  FOREIGN KEY (shipment_id) REFERENCES shipments(id),
  FOREIGN KEY (settlement_id) REFERENCES cod_settlements(id)
) ENGINE=InnoDB;

CREATE TABLE sms_log (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  shipment_id INT UNSIGNED NULL,
  to_phone VARCHAR(20) NOT NULL,
  message VARCHAR(255) NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_ship (shipment_id),
  FOREIGN KEY (shipment_id) REFERENCES shipments(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE audit_log (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id INT UNSIGNED NULL,
  action VARCHAR(30) NOT NULL,
  entity VARCHAR(30) NOT NULL,
  entity_id INT UNSIGNED NULL,
  details VARCHAR(255) NULL,
  ip VARCHAR(45) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_created (created_at)
) ENGINE=InnoDB;

SET FOREIGN_KEY_CHECKS = 0;
SET FOREIGN_KEY_CHECKS = 1;
